-- Name: delete_oldest_rows(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_oldest_rows() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT COUNT(*) FROM sauvgarde WHERE id = NEW.id) > 15 THEN
        DELETE FROM sauvgarde
        WHERE id = NEW.id AND time IN (
            SELECT time
            FROM sauvgarde
            WHERE id = NEW.id
            ORDER BY time
            LIMIT (SELECT COUNT(*) - 15 FROM sauvgarde WHERE id = NEW.id)
        );
    END IF;
    RETURN NEW;
END;
$$;


